-- Dados fictícios para demonstrar a paginação do painel do administrador.
-- Rode DEPOIS de subir o backend uma vez (as tabelas já precisam existir):
--   mysql -u root --default-character-set=utf8mb4 restaurante < backend/database/dados-paginacao.sql
-- Todos os usuários criados aqui têm a senha  Teste12345  e e-mail  clienteNN@demo.com.
-- Pode rodar de novo: ele apaga o que criou antes (imóveis 'Paginação NN', usuários @demo.com e bairros 'Bairro Demo').
SET NAMES utf8mb4;
DELETE c FROM contratos c JOIN ofertas o ON o.id=c.oferta_id JOIN usuarios u ON u.id=o.usuario_id WHERE u.email LIKE 'cliente%@demo.com';
DELETE o FROM ofertas o JOIN usuarios u ON u.id=o.usuario_id WHERE u.email LIKE 'cliente%@demo.com';
DELETE FROM imoveis WHERE titulo LIKE 'Paginação %';
DELETE FROM usuarios WHERE email LIKE 'cliente%@demo.com';
DELETE FROM bairros WHERE nome LIKE 'Bairro Demo %';

